INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES('XJGM','05', 'SQL','SELECT 1 FROM DUAL', 'portfolioCode','N','jjpei','C001',sysdate,'jjpei',sysdate);

DECLARE
---- 实时、买入预占、卖出预占
V_CONTENT_01_02_03 CLOB := 'select RKEY, sum(RVALUE) RVALUE from (
/*T-1日实际与可用现金*/
select m.PORTFOLIO_ID RKEY,nvl(sum(n.AMOUNT),0) as  RVALUE  from PTL_PORTFOLIO m 	
  LEFT JOIN PTL_CASH_POSITION n ON m.PORTFOLIO_ID=n.PORTFOLIO_ID AND  n.HODING_TYPE=''03'' AND n.CDATE =date''${valDate}''-1	
  where  m.PORTFOLIO_TYPE IN (''01'',''02'') AND m.MDATE>date''${valDate}''  group by m.PORTFOLIO_ID	
union all	
select m.PORTFOLIO_ID RKEY,nvl(sum(n.AMOUNT),0) as  RVALUE  from PTL_PORTFOLIO m 	
  LEFT JOIN PTL_CASH_POSITION_FLOW n ON m.PORTFOLIO_ID=n.PORTFOLIO_ID AND  n.HODING_TYPE=''01'' AND n.CDATE >=date''${valDate}''-1	
  where  m.PORTFOLIO_TYPE IN (''01'',''02'') AND m.MDATE>date''${valDate}''  group by m.PORTFOLIO_ID
) group by RKEY';

----事后(日间)
V_CONTENT_04 CLOB := 'select nvl(SUM(RVALUE),0) as RVALUE from (
  /*T日实际现金*/
  select nvl(sum(AMOUNT),0) as  RVALUE from PTL_CASH_POSITION
    where  PORTFOLIO_ID in ${portfolioCode} and HODING_TYPE=''03'' and CDATE =date''${valDate}''
  /*T日可用现金*/
  UNION ALL
    select nvl(sum(AMOUNT),0) as  RVALUE from PTL_CASH_POSITION_FLOW
    where  PORTFOLIO_ID in ${portfolioCode} and HODING_TYPE=''01'' and CDATE >=date''${valDate}''
)';

----事后(日终)
V_CONTENT_05 CLOB := 'SELECT SUM((nvl(t.DSC_COST_AMT,0)+nvl(t.TDY_INTINCEXP,0))) as RVALUE FROM PTL_SEC_VALUTION t 
INNER JOIN PTL_CAPACCT_INFO n ON t.PORTFOLIO_ID = n.PORTFOLIO_ID AND t.FINPROD_ID = n.ACCT_NO  
where t.PORTFOLIO_ID in ${portfolioCode} and t.CDATE=date''${valDate}''';
BEGIN
    UPDATE RSK_ISUP_INDICATOR_PARA_DTL SET CONTENT = V_CONTENT_01_02_03 WHERE PARA_CODE = 'XJGM' and PARA_GRANULARITY in('01','02','03');

    UPDATE RSK_ISUP_INDICATOR_PARA_DTL SET CONTENT = V_CONTENT_04 WHERE PARA_CODE = 'XJGM' and PARA_GRANULARITY ='04';

    UPDATE RSK_ISUP_INDICATOR_PARA_DTL SET CONTENT = V_CONTENT_05 WHERE PARA_CODE = 'XJGM' and PARA_GRANULARITY = '05';
END;
/

